MAPF Environment and Core Utilities
"""
import numpy as np
import heapq
from collections import defaultdict
import time

class MAPFEnv:
    """Multi-Agent Path Finding Environment"""

    def __init__(self, grid, starts, goals):
        """
        grid: 2D numpy array, 0=free, -1=obstacle
        starts: list of (row, col) tuples
        goals: list of (row, col) tuples
        """
        self.grid = grid
        self.rows, self.cols = grid.shape
        self.starts = starts
        self.goals = goals
        self.num_agents = len(starts)
        self.obstacles = set(zip(*np.where(grid == -1)))

    def is_free(self, r, c):
        return 0 <= r < self.rows and 0 <= c < self.cols and self.grid[r, c] == 0

    def neighbors(self, r, c):
        """Return valid neighbors including wait action"""
        result = []
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1),(0,0)]:
            nr, nc = r+dr, c+dc
            if (dr, dc) == (0, 0):
                result.append((r, c))  # wait
            elif self.is_free(nr, nc):
                result.append((nr, nc))
        return result

    def manhattan(self, p1, p2):
        return abs(p1[0]-p2[0]) + abs(p1[1]-p2[1])

    def astar(self, start, goal, occupied=None, max_t=None):
        """Single-agent A* on space-time graph. occupied: dict {(r,c,t): agent_id}"""
        if occupied is None:
            occupied = {}

        open_set = [(self.manhattan(start, goal), 0, start, 0, [start])]
        closed = set()

        while open_set:
            f, g, pos, t, path = heapq.heappop(open_set)

            if pos == goal and (max_t is None or t >= max_t):
                return path

            if (pos, t) in closed:
                continue
            closed.add((pos, t))

            next_t = t + 1
            for npos in self.neighbors(pos[0], pos[1]):
                # Check vertex collision
                if (npos, next_t) in occupied:
                    continue
                # Check edge collision (swap)
                if (pos, next_t) in occupied and occupied[(pos, next_t)] != -1:
                    # Someone else will be at our current pos at next_t from a different location
                    pass  # simplified: just check vertex

                if (npos, next_t) not in closed:
                    new_g = g + 1
                    h = self.manhattan(npos, goal)
                    heapq.heappush(open_set, (new_g + h, new_g, npos, next_t, path + [npos]))

        return None  # No path found

    def astar_static(self, start, goal):
        """Simple A* ignoring other agents"""
        if start == goal:
            return [start]
        open_set = [(self.manhattan(start, goal), 0, start, [start])]
        closed = set()

        while open_set:
            f, g, pos, path = heapq.heappop(open_set)
            if pos == goal:
                return path
            if pos in closed:
                continue
            closed.add(pos)
            for npos in self.neighbors(pos[0], pos[1]):
                if npos == pos:  # skip wait for static
                    continue
                if npos not in closed:
                    new_g = g + 1
                    h = self.manhattan(npos, goal)
                    heapq.heappush(open_set, (new_g + h, new_g, npos, path + [npos]))
        return None

    def count_collisions(self, paths):
        """Count vertex and edge collisions"""
        collisions = 0
        max_len = max(len(p) for p in paths) if paths else 0

        # Extend paths (stay at goal)
        extended = []
        for p in paths:
            ext = list(p)
            while len(ext) < max_len:
                ext.append(ext[-1])
            extended.append(ext)

        for t in range(max_len):
            # Vertex collisions
            positions = {}
            for i, p in enumerate(extended):
                pos = p[t]
                if pos in positions:
                    collisions += 1
                else:
                    positions[pos] = i

            # Edge collisions (swap)
            if t > 0:
                for i in range(len(extended)):
                    for j in range(i+1, len(extended)):
                        if extended[i][t] == extended[j][t-1] and extended[i][t-1] == extended[j][t]:
                            collisions += 1

        return collisions

    def is_collision_free(self, paths):
        return self.count_collisions(paths) == 0

    def solution_cost(self, paths):
        """Sum of path lengths"""
        return sum(len(p) - 1 for p in paths)  # -1 because path includes start


def generate_agents(grid, num_agents, seed=42):
    """Generate random start/goal positions on free cells"""
    rng = np.random.RandomState(seed)
    free_cells = list(zip(*np.where(grid == 0)))

    if len(free_cells) < 2 * num_agents:
        return None, None

    rng.shuffle(free_cells)
    starts = free_cells[:num_agents]
    goals = free_cells[num_agents:2*num_agents]

    # Make sure start != goal for each agent
    for i in range(num_agents):
        if starts[i] == goals[i]:
            for j in range(2*num_agents, len(free_cells)):
                if free_cells[j] != starts[i]:
                    goals[i] = free_cells[j]
                    break

    return starts, goals


def load_map_instance(map_path, num_agents, seed=42):
    """Load a map and generate agent instances"""
    grid = np.load(map_path)
    starts, goals = generate_agents(grid, num_agents, seed)
    if starts is None:
        return None
    return MAPFEnv(grid, starts, goals)
